  "Quelle que soit la formule, l'assureur ne paie rien pour un navire parti avec moins de 40 % d'état. Les primes sont prélevées chaque jour.": "Whatever the plan, the insurer pays nothing for a ship that sailed below 40% condition. Premiums are charged daily.",
