  "La banque prête jusqu'à 60 % de la valeur de votre flotte, plus une part selon votre réputation. Un découvert coûte 20 %/an ; trop profond, la banque saisit un navire.": "The bank lends up to 60% of your fleet's value, plus a share depending on your reputation. An overdraft costs 20%/year; too deep, and the bank seizes a ship.",
