  "Qualité du registre": "Registry quality",
  "Réputation : {0}/100": "Reputation: {0}/100",
  "Livrer à l'heure fait monter la réputation ; les retards, contrats abandonnés, naufrages et saisies la font chuter. Elle ouvre l'accès aux meilleurs contrats et baisse le taux des prêts.": "Delivering on time raises your reputation; delays, abandoned contracts, sinkings and seizures make it drop. It opens access to the best contracts and lowers loan rates.",
  "{0} livraisons, dont {1} en retard · {2} ports desservis.": "{0} deliveries, {1} of them late · {2} ports served.",
  "Changer de port d'attache": "Change home port",
  "Transférer le siège change le pavillon de toute la flotte (impôts, salaires, crédit). Coût : {0}.": "Moving headquarters changes the flag of the whole fleet (taxes, wages, credit). Cost: {0}.",
  "Nouveau port d'attache": "New home port",
  "S'installer à {0} ?": "Move to {0}?",
