  "{0} (piraterie {1})": "{0} ({1} piracy)",
  "☠ Votre route traverse : {0}. Risque d'attaque ≈ {1}. Défense {2}{3} : chance de repousser une attaque ordinaire {4}, les plus dangereuses {5}. Sans citadelle, un navire abordé est détourné contre rançon. Ralentir allonge le passage ; aller vite aide à semer les pirates.": "☠ Your route crosses: {0}. Risk of attack ≈ {1}. Defence {2}{3}: chance of repelling an ordinary attack {4}, the most dangerous ones {5}. Without a citadel, a boarded ship is hijacked for ransom. Slowing down lengthens the passage; going fast helps outrun pirates.",
  "✔ Attaque repoussée": "✔ Attack repelled",
  "⚠ Navire pillé, équipage sain et sauf": "⚠ Ship looted, crew safe and sound",
  "✖ Navire détourné": "✖ Ship hijacked",
