  "Les pirates réclament {0}. L'équipage est retenu à bord.": "The pirates demand {0}. The crew is held on board.",
  "Payer : le navire est libéré en 3 à 7 jours. Négocier : vous paierez environ {0}, mais la captivité durera 1 à 2 mois (contrat en retard, réputation entamée).": "Pay: the ship is released in 3 to 7 days. Negotiate: you'll pay about {0}, but the captivity will last 1 to 2 months (late contract, damaged reputation).",
  "Négocier (≈ {0})": "Negotiate (≈ {0})",
