  "Rançon versée : {0}. Le {1} sera libéré dans {2} jours.": "Ransom paid: {0}. The {1} will be released in {2} days.",
  "🚔 Eaux surveillées sur la route ({0}) : risque d'être contrôlé ≈ {1}. Chance de filer {2}, que la fouille ne trouve rien {3} : au total, colis saisi ≈ {4}. Les garde-côtes ne se laissent pas acheter.": "🚔 Patrolled waters on the route ({0}): risk of being checked ≈ {1}. Chance of getting away {2}, of the search finding nothing {3}: overall, parcel seized ≈ {4}. Coast guards can't be bought.",
  "✔ Contrôle évité": "✔ Check avoided",
  "✔ Fouille sans résultat": "✔ Search found nothing",
  "✖ Colis saisi : amende {0}, navire retenu {1} jours": "✖ Parcel seized: fine {0}, ship held {1} days",
  "Contrôle en mer — {0}": "Check at sea — {0}",
  "Sobriété": "Economy",
  "Autonomie": "Range",
  "Polyvalence": "Versatility",
  "Jeunesse": "Youth",
  "moins de 0,1 %": "less than 0.1%",
  "✖ Sans assurance (votre choix, au Bureau) : un naufrage, une réclamation ou une pollution serait entièrement à vos frais.": "✖ Uninsured (your choice, at the Office): a sinking, a claim or pollution would be entirely at your expense.",
  "✖ Non assuré — sous {0} % d'état au départ, l'assureur ne couvre rien. Un naufrage ou une réclamation serait entièrement à vos frais.": "✖ Not insured — below {0}% condition on departure, the insurer covers nothing. A sinking or a claim would be entirely at your expense.",
  "◐ Coque seule": "◐ Hull only",
  "— la coque est remboursée à {0} %, mais réclamations des chargeurs et pollution sont à vos frais (tant que l'état au départ reste d'au moins {1} %).": "— the hull is reimbursed at {0}%, but shippers' claims and pollution are at your expense (as long as the departure condition stays at least {1}%).",
  "✔ Assuré": "✔ Insured",
  "(formule complète) — coque à {0} %, réclamations et pollution couvertes, tant que l'état au départ reste d'au moins {1} %.": "(full cover) — hull at {0}%, claims and pollution covered, as long as the departure condition stays at least {1}%.",
  "Votre route longe {0}.": "Your route runs along {0}.",
  "Votre route reste au large des côtes sensibles.": "Your route stays clear of sensitive coasts.",
  "En cas de marée noire, nettoyage jusqu'à {0} : l'assurance paie, il vous resterait {1} de franchise.": "In case of an oil spill, clean-up up to {0}: insurance pays, leaving you a {1} excess.",
  ", votre assurance ne couvrant pas la pollution.": ", as your insurance doesn't cover pollution.",
  "car le navire n'est pas en état, et le pays touché vous fermerait ses ports un an.": "because the ship isn't seaworthy, and the affected country would ban you from its ports for a year.",
  "En cas de marée noire, nettoyage jusqu'à {0}, à vos frais (jusqu'à {1}){2}": "In case of an oil spill, clean-up up to {0}, at your expense (up to {1}){2}",
  "☣ Cargaison polluante. {0} {1}": "☣ Polluting cargo. {0} {1}",
  "🧭 Le capitaine juge le risque d'incident": "🧭 The captain rates the incident risk as",
  "Un équipage plus expérimenté saurait le chiffrer.": "A more experienced crew could put a figure on it.",
  "🧭 Vos officiers estiment {0} à {1} incidents par an, et un risque de naufrage de": "🧭 Your officers estimate {0} to {1} incidents per year, and a risk of sinking of",
  "par an.": "per year.",
  "🧭 Le chef mécanicien compte {0} incident{1} par an et un risque de naufrage de": "🧭 The chief engineer counts {0} incident{1} per year and a risk of sinking of",
  "Sur ce voyage : {0} de risque d'incident, {1} de risque de naufrage.": "On this voyage: {0} risk of an incident, {1} risk of sinking.",
  "Sur ce voyage : environ {0} de risque d'incident.": "On this voyage: about {0} risk of an incident.",
  "élevé": "high",
  "{0} inspecte sévèrement les navires usés": "{0} strictly inspects worn ships",
  "{0} contrôle parfois les navires usés": "{0} sometimes checks worn ships",
  "⚠ {0} : risque de détention {1} (amende et remise en état à {2} % à vos frais, que vous ayez l'argent ou non). Réparez au-dessus de {3} % pour l'éviter.": "⚠ {0}: risk of detention {1} (fine and overhaul to {2}% at your expense, whether you have the money or not). Repair above {3}% to avoid it.",
  "⚠ Sous {0} %, les ports exigeants (Europe, Amérique du Nord, Japon, Corée, Australie, Singapour) peuvent retenir ce navire.": "⚠ Below {0}%, strict ports (Europe, North America, Japan, Korea, Australia, Singapore) may detain this ship.",
  "Avis de l'expert maritime sur le risque d'incident": "Marine surveyor's opinion on the incident risk",
