  "📦 Colis caché à bord, à livrer ici.": "📦 Parcel hidden on board, to deliver here.",
  "📦 Colis caché à bord, à livrer à {0}.": "📦 Parcel hidden on board, to deliver to {0}.",
  "Risque de fouille à {0} :": "Risk of a search in {0}:",
  "Si la douane le trouve : amende de {0} et 10 à 25 jours d'immobilisation.": "If customs find it: {0} fine and 10 to 25 days of detention.",
  "Un arrangement sera peut-être possible.": "An arrangement may be possible.",
  "⚖ Le {0} a commercé avec un pays sous embargo ({1}, le {2}) : {3} applique les sanctions. Risque d'amende {4} ({5}).": "⚖ The {0} traded with a country under embargo ({1}, on {2}): {3} enforces the sanctions. Risk of a fine {4} ({5}).",
  "⚖ {0} est sous embargo : y commercer marquera le navire pendant {1} mois. Pendant ce temps, chaque escale en Europe, en Amérique du Nord, au Japon, en Corée ou en Océanie peut coûter une amende.": "⚖ {0} is under embargo: trading there will flag the ship for {1} months. During that time, every port call in Europe, North America, Japan, Korea or Oceania may cost a fine.",
  "🤫 Propositions discrètes": "🤫 Discreet offers",
  "Un intermédiaire cherche un navire pour un petit colis, à cacher à bord en plus de votre cargaison. Payé en liquide à la livraison. Les cargos le cachent bien mieux que les pétroliers ; un équipage aguerri est plus discret.": "A middleman is looking for a ship for a small parcel, to hide on board alongside your cargo. Paid in cash on delivery. General cargo ships hide it far better than tankers; a seasoned crew is more discreet.",
  "Un colis est déjà caché à bord (pour {0}).": "A parcel is already hidden on board (for {0}).",
  "Personne ne vous a approché aujourd'hui.": "Nobody approached you today.",
  "📦 Colis pour": "📦 Parcel for",
  "À livrer avant le {0}. Risque de fouille à l'arrivée :": "To deliver before {0}. Risk of a search on arrival:",
  "(et à chaque escale en route). Si la douane le trouve : amende de {0}, navire immobilisé 10 à 25 jours, réputation entachée.": "(and at every port call on the way). If customs find it: {0} fine, ship held 10 to 25 days, tarnished reputation.",
  "⚖ Pays sous embargo ({0}) : ses importations se paient cher, son brut est bradé et le fret y est mieux payé, mais un navire qui y commerce risque des amendes pendant un an dans les pays qui appliquent les sanctions.": "⚖ Country under embargo ({0}): its imports pay well, its crude is sold off cheaply and freight there pays better, but a ship that trades there risks fines for a year in countries that enforce sanctions.",
  "{0} applique les sanctions : un navire passé par un pays sous embargo dans l'année peut y être mis à l'amende.": "{0} enforces the sanctions: a ship that called at a country under embargo within the year may be fined there.",
  ", fonctionnaires réputés accommodants": ", officials known to be accommodating",
  "Des intermédiaires y proposent des colis discrets.": "Middlemen offer discreet parcels here.",
  "Douane {0}{1}.{2}": "Customs: {0}{1}.{2}",
  "La douane a trouvé le colis": "Customs found the parcel",
