  "Hambourg": "Hamburg",
  "Porte de l'industrie allemande. Accès par l'Elbe : tirant d'eau limité.": "Gateway to German industry. Access via the Elbe: limited draught.",
  "Grand port céréalier. Pavillon solide mais équipages coûteux.": "A major grain port. A solid flag but costly crews.",
