  "Gênes": "Genoa",
  "Porte maritime de l'Italie du Nord : de l'industrie à exporter, mais taxes et salaires élevés.": "Northern Italy's gateway to the sea: industry to export, but high taxes and wages.",
  "Algésiras": "Algeciras",
  "Au pied du rocher de Gibraltar : le grand plein de l'Europe, au carrefour de l'Atlantique et de la Méditerranée.": "At the foot of the Rock of Gibraltar: Europe's big bunkering stop, where the Atlantic meets the Mediterranean.",
