  "Cargo": "General cargo ship",
  "Petit et économique. Entre partout, idéal pour démarrer.": "Small and economical. Goes everywhere, ideal for starting out.",
  "Vieux cargo": "Old cargo ship",
  "Un cargo des années 60 aux mâts de charge. Donné, mais gourmand en fuel et en marins.": "A 1960s cargo ship with derricks. Almost given away, but thirsty for fuel and sailors.",
  "Cargo polyvalent": "Multipurpose cargo ship",
  "Transporte presque tout, avec ses propres grues.": "Carries almost anything, with its own cranes.",
  "Navire colis lourds": "Heavy-lift ship",
  "Deux grues géantes pour les turbines, chaudières et engins hors normes. Seul à prendre les colis lourds.": "Two giant cranes for turbines, boilers and outsized machinery. The only ship that takes heavy lifts.",
  "Vraquier Handysize": "Handysize bulk carrier",
  "Vraquier": "Bulk carrier",
  "Le cheval de trait du vrac : céréales, minerai, charbon, engrais.": "The workhorse of bulk: grain, ore, coal, fertiliser.",
  "Vraquier Supramax": "Supramax bulk carrier",
  "Plus grand, toujours équipé de grues : il charge et décharge partout.": "Bigger, still fitted with cranes: it loads and unloads anywhere.",
  "Vraquier Panamax": "Panamax bulk carrier",
  "Sans grues, taillé pour le canal de Panama. Charbon et céréales en masse.": "No cranes, built for the Panama Canal. Coal and grain in bulk.",
  "Vraquier Capesize": "Capesize bulk carrier",
  "Trop grand pour les canaux, il passe par le cap Horn. Le roi du minerai de fer.": "Too big for the canals, it goes round Cape Horn. The king of iron ore.",
  "Vieux pétrolier": "Old tanker",
  "Pétrolier": "Tanker",
  "Passerelle au milieu, machine à l'arrière : un pétrolier des années 70. Bon marché, assoiffé.": "Bridge amidships, engine aft: a 1970s tanker. Cheap, thirsty.",
  "Pétrolier de produits (MR)": "Product tanker (MR)",
  "Brut et produits raffinés. Rentable, mais exigeant en ports.": "Crude and refined products. Profitable, but demanding about ports.",
  "Chimiquier": "Chemical tanker",
  "Des dizaines de citernes inox séparées : produits chimiques et petits lots.": "Dozens of separate stainless steel tanks: chemicals and small parcels.",
  "Pétrolier Aframax": "Aframax tanker",
  "Le pétrolier des mers régionales : mer du Nord, Méditerranée, Caraïbes.": "The tanker of regional seas: North Sea, Mediterranean, Caribbean.",
  "Pétrolier Suezmax": "Suezmax tanker",
  "Le plus grand pétrolier à franchir le canal de Suez chargé.": "The largest tanker that can pass through the Suez Canal laden.",
  "Superpétrolier (VLCC)": "Supertanker (VLCC)",
  "300 000 tonnes de brut. Trop profond pour Suez : il fait le tour de l'Afrique.": "300,000 tonnes of crude. Too deep for Suez: it sails around Africa.",
  "Géant des mers (ULCC)": "Giant of the seas (ULCC)",
  "Le plus grand navire jamais construit. Seule une poignée de terminaux pétroliers peut l'accueillir.": "The largest ship ever built. Only a handful of oil terminals can take it.",
  "Gazier (GPL)": "Gas carrier (LPG)",
  "Gazier": "Gas carrier",
  "Cuves cylindriques sous pression pour le butane et le propane.": "Cylindrical pressure tanks for butane and propane.",
  "Méthanier (GNL)": "LNG carrier",
  "Le gaz naturel à −162 °C dans quatre sphères géantes. Le navire de prestige par excellence.": "Natural gas at −162 °C in four giant spheres. The ultimate prestige ship.",
  "Porte-conteneurs feeder": "Feeder container ship",
  "1 700 conteneurs. Rapide, gourmand en carburant.": "1,700 containers. Fast, fuel-hungry.",
  "Porte-conteneurs Panamax": "Panamax container ship",
  "4 500 conteneurs à 21 nœuds. Il franchit les nouvelles écluses de Panama.": "4,500 containers at 21 knots. It fits the new Panama locks.",
  "Porte-conteneurs géant": "Giant container ship",
  "20 000 conteneurs, 400 mètres : le vaisseau amiral du commerce mondial.": "20,000 containers, 400 metres: the flagship of world trade.",
  "Transporteur de voitures": "Car carrier",
  "Spécialisé": "Specialised",
  "Une boîte à chaussures flottante : 6 500 véhicules sur douze ponts.": "A floating shoebox: 6,500 vehicles on twelve decks.",
  "Navire frigorifique": "Reefer ship",
  "Coque blanche et cales à −25 °C : fruits et viandes, à toute vitesse.": "White hull and holds at −25 °C: fruit and meat, at full speed.",
  "Équipage de base": "Basic crew",
  "de base": "basic",
  "Le minimum réglementaire. Le capitaine ne vous donne qu'un avis général sur les dangers.": "The regulatory minimum. The captain only gives you a general opinion on the dangers.",
  "Équipage confirmé": "Experienced crew",
  "confirmé": "experienced",
  "Des officiers expérimentés : moins d'incidents, et une estimation chiffrée des risques.": "Experienced officers: fewer incidents, and a figured estimate of the risks.",
  "Équipage chevronné": "Veteran crew",
  "chevronné": "veteran",
  "Le chef mécanicien connaît chaque boulon : beaucoup moins d'incidents, risques évalués précisément, voyage par voyage.": "The chief engineer knows every bolt: far fewer incidents, risks assessed precisely, voyage by voyage.",
