  "Aux mains d'un gang à {0} — rançon de {1}": "Held by a gang at {0} — ransom of {1}",
  "Aide d'urgence : payée à prix coûtant partiel (vous perdrez de l'argent), mais elle rend de la réputation.": "Emergency aid: paid at partial cost (you will lose money), but it restores reputation.",
  "❤ aide d'urgence": "❤ emergency aid",
  "❤ {0} : aide d'urgence, payée à prix coûtant partiel. Réputation +{1} si elle arrive à l'heure.": "❤ {0}: emergency aid, paid at partial cost. Reputation +{1} if it arrives on time.",
  "Plafond de votre réputation : {0}.": "Your reputation ceiling: {0}.",
  "Un gang de ce port en veut à votre compagnie : risque de saisie à l'escale.": "A gang in this port has a grudge against your company: risk of seizure on calling.",
  "⚠ gang": "⚠ gang",
  "livraison noire": "dark delivery",
  "☠ Infamie : {0}. Votre réputation ne pourra plus dépasser {1}/100 : c'est définitif. L'aide d'urgence la fait remonter jusqu'à ce plafond.": "☠ Infamy: {0}. Your reputation can no longer exceed {1}/100: this is permanent. Emergency aid brings it back up to that ceiling.",
  "L'aide d'urgence est arrivée": "Emergency aid has arrived",
  "Les cales sont occupées par la cargaison noire.": "The holds are taken up by the dark cargo.",
  "Armes de guerre pour une milice": "Weapons of war for a militia",
  "Drogue en quantité industrielle": "Drugs in industrial quantities",
  "Passagers clandestins entassés dans la cale": "Stowaway migrants crammed into the hold",
  "armes de guerre pour une milice": "weapons of war for a militia",
  "drogue en quantité industrielle": "drugs in industrial quantities",
  "passagers clandestins entassés dans la cale": "stowaway migrants crammed into the hold",
  "À {0}, les contacts du {1} proposent une « vraie » affaire : {2} pour {3}, {4}.": "At {0}, the {1}'s contacts offer a \"real\" job: {2} for {3}, {4}.",
  "Les cales doivent être vides.": "The holds must be empty.",
