  "Cargaison noire embarquée pour {0}": "Dark cargo loaded for {0}",
  "Affaire noire refusée à {0}": "Dark job refused at {0}",
  "confisqué": "impounded",
  "otages": "hostages",
  "recrutement": "hiring",
  "La justice de {0} confisque le {1} ({2}) après la découverte de sa cargaison. Caution pour le récupérer : {3}.": "The courts of {0} impound the {1} ({2}) after its cargo is discovered. Bail to get it back: {3}.",
  "La justice de {0} confisque le {1} ({2}). Caution pour le récupérer : {3}.": "The courts of {0} impound the {1} ({2}). Bail to get it back: {3}.",
  "À {0}, des hommes armés s'emparent du {1} ({2}) et de son équipage. Ils réclament {3}.": "At {0}, armed men seize the {1} ({2}) and its crew. They demand {3}.",
  "À {0}, des hommes armés enlèvent l'équipage du {1} ({2}). Ils réclament {3}.": "At {0}, armed men kidnap the crew of the {1} ({2}). They demand {3}.",
  "Confisqué par la justice à {0}": "Impounded by the courts at {0}",
  "Pris par un gang à {0}": "Taken by a gang at {0}",
  "Équipage enlevé à {0}": "Crew kidnapped at {0}",
  "Caution versée ({0})": "Bail paid ({0})",
  "Rançon versée ({0})": "Ransom paid ({0})",
  "Équipage abandonné aux ravisseurs ; nouvel équipage recruté": "Crew abandoned to the kidnappers; new crew hired",
  "{0} refuse de payer pour l'équipage du {1}, enlevé à {2}.": "{0} refuses to pay for the crew of the {1}, kidnapped at {2}.",
  "{0} abandonne le {1}, confisqué à {2}.": "{0} abandons the {1}, impounded at {2}.",
  "{0} abandonne le {1} aux mains d'un gang à {2}.": "{0} abandons the {1} to a gang at {2}.",
  "La cargaison noire du {0} arrive trop tard : les acheteurs ne veulent plus en entendre parler, et vos contacts de {1} vous en veulent.": "The {0}'s dark cargo arrives too late: the buyers want nothing more to do with it, and your contacts in {1} hold it against you.",
  "Scandale : la douane de {0} découvre à bord du {1} ({2}) {3}. Amende de {4}, l'équipage est arrêté.": "Scandal: customs at {0} discover {3} aboard the {1} ({2}). Fine of {4}, the crew is arrested.",
  "Cargaison noire livrée à {0}": "Dark cargo delivered at {0}",
  "La cargaison noire du {0} est livrée à {1} : {2} en liquide. Personne n'a rien vu.": "The {0}'s dark cargo is delivered at {1}: {2} in cash. Nobody saw a thing.",
  "Des combats d'une rare violence éclatent près de {0} : les miliciens disposaient d'armes lourdes toutes neuves, arrivées par la mer selon la presse.": "Fighting of rare violence breaks out near {0}: the militiamen had brand-new heavy weapons, which arrived by sea according to the press.",
  "Attentat à {0} : une voiture piégée fait de nombreuses victimes. Les enquêteurs remontent la piste d'explosifs débarqués il y a peu.": "Attack in {0}: a car bomb kills and injures many. Investigators are tracing explosives landed recently.",
  "{0} : les urgences débordent, vague d'overdoses liée à une drogue très pure arrivée en masse.": "{0}: emergency rooms overflow, a wave of overdoses linked to very pure drugs arriving in bulk.",
  "Guerre des gangs à {0} après l'arrivée d'une énorme quantité de drogue : plusieurs morts dans les quartiers du port.": "Gang war in {0} after a huge quantity of drugs arrives: several dead in the port districts.",
  "Drame à {0} : des passagers clandestins retrouvés à bout de forces dans la cale d'un cargo ; plusieurs n'ont pas survécu.": "Tragedy in {0}: stowaways found exhausted in a cargo ship's hold; several did not survive.",
  "{0} : des dizaines de migrants débarqués de nuit, aussitôt exploités par des réseaux.": "{0}: dozens of migrants landed at night, immediately exploited by criminal networks.",
  "{0} : des faux billets de très bonne qualité inondent les commerces du port.": "{0}: very high-quality counterfeit banknotes flood the port's shops.",
  "{0} : la police signale une hausse soudaine de la consommation de drogue.": "{0}: police report a sudden rise in drug use.",
  "Explosion meurtrière à {0} : les enquêteurs parlent d'un engin fabriqué avec du matériel arrivé récemment.": "Deadly explosion in {0}: investigators speak of a device built with material that arrived recently.",
  "{0} : des médicaments contrefaits retrouvés en pharmacie, plusieurs malades hospitalisés.": "{0}: counterfeit medicines found in pharmacies, several patients hospitalised.",
  "C'est votre cargaison, livrée à {0} le {1}.": "It was your cargo, delivered at {0} on {1}.",
  "Le colis livré à {0} le {1} y est peut-être pour quelque chose.": "The parcel delivered at {0} on {1} may have had something to do with it.",
  "{0} à {1} : {2} cherche des navires pour l'aide d'urgence (contrats à prix coûtant, partiels).": "{0} in {1}: {2} is looking for ships for emergency aid (contracts at partial cost).",
  "{0} sur la côte": "{0} on the coast",
  "Séisme": "Earthquake",
  "Inondations": "Floods",
  "Glissements de terrain": "Landslides",
  "{0} achemine l'aide d'urgence de {1} à {2} avec le {3}.": "{0} carries {1}'s emergency aid to {2} aboard the {3}.",
  "est libéré par ses ravisseurs": "is released by its captors",
  "est rendu par la justice": "is returned by the courts",
  "a un nouvel équipage": "has a new crew",
  "Le {0} a livré l'aide d'urgence de {1} à {2}, mais en retard : pas de gain de réputation.": "The {0} delivered {1}'s emergency aid to {2}, but late: no reputation gain.",
  "Le {0} a livré l'aide d'urgence de {1} à {2}. La population vous remercie : réputation +{3}.": "The {0} delivered {1}'s emergency aid to {2}. The people thank you: reputation +{3}.",
  "{0} : participation aux frais": "{0}: contribution to costs",
  "Escales sans frontières": "Ports Without Borders",
  "Les Amarres Solidaires": "Solidarity Moorings",
  "Fondation Bouée de Secours": "Lifebuoy Foundation",
  "Affaires noires : livrer des colis embarqués dans un port louche sous embargo (Bandar Abbas, Puerto La Cruz, Novorossiïsk, Nampo) gagne la confiance des gangs. Ils proposent alors de « vraies » affaires : armes pour une milice, drogue en quantité industrielle, passagers clandestins. Énormément payées, mais c'est un point de non-retour : chaque affaire ajoute de l'infamie, qui abaisse pour toujours le plafond de votre réputation, et la douane les trouve plus facilement (navire confisqué). Refuser n'est pas sans risque : le gang peut prendre le navire ou l'équipage (rançon), puis vous en vouloir quelques mois. Ce que vous livrez finit parfois dans les nouvelles. À l'inverse, après une catastrophe, des associations cherchent des navires pour l'aide d'urgence : contrats à perte, mais qui rendent de la réputation.": "Dark jobs: delivering parcels picked up in a shady port under embargo (Bandar Abbas, Puerto La Cruz, Novorossiysk, Nampo) earns the gangs' trust. They then offer \"real\" jobs: weapons for a militia, drugs in industrial quantities, stowaway migrants. Hugely paid, but a point of no return: each job adds infamy, which permanently lowers your reputation ceiling, and customs find them more easily (ship impounded). Refusing is not without risk: the gang may take the ship or the crew (ransom), then hold a grudge for a few months. What you deliver sometimes ends up in the news. Conversely, after a disaster, charities look for ships for emergency aid: loss-making contracts that restore reputation.",
  // Bureau > Résultats > Par navire
  "Par navire": "By ship",
  "Ce que rapporte chaque navire depuis son achat : fret facturé, marges de négoce et affaires discrètes, moins tout ce qu'il coûte (carburant, équipage, entretien et assurance, ports, réparations, sinistres). Sans les intérêts, les impôts ni le prix du navire.": "What each ship has earned since it was bought: freight invoiced, trading margins and discreet deals, minus everything it costs (fuel, crew, maintenance and insurance, ports, repairs, claims). Excludes interest, taxes and the ship's price.",
  "Aucun navire pour l'instant.": "No ships yet.",
