  // Visite guidée
  "Premiers pas · {0}/{1}": "First steps · {0}/{1}",
  "Passer la visite": "Skip the tour",
  "Compris": "Got it",
  "Terminer": "Finish",
  "Votre premier navire": "Your first ship",
  "Tout commence chez le courtier : touchez 🏗️ pour acheter votre premier navire.": "It all starts at the broker: tap 🏗️ to buy your first ship.",
  "Les navires d'occasion sont les plus abordables. Regardez l'âge et l'état : un vieux navire coûte moins cher, mais tombe plus souvent en panne. Touchez « Acheter » sur celui qui vous plaît.": "Second-hand ships are the most affordable. Check age and condition: an old ship costs less but breaks down more often. Tap “Buy” on the one you like.",
  "Rien d'abordable ici : regardez l'autre onglet.": "Nothing affordable here: look at the other tab.",
  "Un premier contrat": "A first contract",
  "Voici les contrats du port : la paie, la destination, la date limite et le bénéfice estimé. Choisissez-en un qui rapporte bien sans « retard probable », puis « Accepter » : le navire chargera et partira tout seul.": "These are the port's contracts: pay, destination, deadline and estimated profit. Pick one that pays well without “likely late”, then “Accept”: the ship will load and sail on its own.",
  "Aucun contrat possible pour ce navire ici. Partez à vide vers un port mieux fourni (onglet « Appareiller »), ou lancez le temps : de nouvelles offres arrivent chaque jour.": "No contract this ship can take here. Sail empty to a busier port (“Set sail” tab), or start time: new offers arrive every day.",
  "Le trajet, le carburant et les risques sont estimés ici. Appareillez : une fois là-bas, prenez un contrat.": "The trip, fuel and risks are estimated here. Set sail: once there, take a contract.",
  "Choisissez une destination proche qui a des contrats pour ce navire (le nombre est indiqué sur chaque port).": "Pick a nearby destination with contracts for this ship (the number is shown on each port).",
  "Ouvrez l'onglet « Contrats » : ce sont les cargaisons à transporter au départ de ce port.": "Open the “Contracts” tab: these are the cargoes to carry from this port.",
  "Ouvrez votre navire : touchez 🚢 Flotte, ou le navire sur la carte.": "Open your ship: tap 🚢 Fleet, or the ship on the map.",
  "Être payé": "Getting paid",
  "Le client paie à la livraison… en principe : un retard, une avarie ou un client peu fiable changent la somme. Encaissez maintenant, ou plus tard depuis la Flotte.": "The client pays on delivery… in principle: a delay, damage or an unreliable client changes the amount. Collect now, or later from the Fleet.",
  "Le temps": "Time",
  "Lancez le temps avec ▶ (▶▶ et ▶▶▶ vont plus vite). Le jeu se met en pause tout seul quand un navire a besoin de vous.": "Start time with ▶ (▶▶ and ▶▶▶ go faster). The game pauses by itself when a ship needs you.",
  "Le {0} fait route. En haut : sa destination, sa date d'arrivée et son carburant. Touchez un navire sur la carte pour le suivre.": "The {0} is under way. At the top: its destination, arrival date and fuel. Tap a ship on the map to follow it.",
  "Le {0} fait route. La Flotte 🚢 montre où sont vos navires et ce qu'ils font ; touchez un navire sur la carte pour le suivre.": "The {0} is under way. The Fleet 🚢 shows where your ships are and what they are doing; tap a ship on the map to follow it.",
  "Le {0} attend vos ordres : le jeu s'est mis en pause. Prenez un nouveau contrat, ou partez à vide vers un port mieux fourni (onglet « Appareiller »).": "The {0} is waiting for orders: the game has paused. Take a new contract, or sail empty to a busier port (“Set sail” tab).",
  "Le {0} attend vos ordres : le jeu s'est mis en pause. Ouvrez-le (🚢 Flotte, ou sur la carte) pour lui donner un nouveau contrat.": "The {0} is waiting for orders: the game has paused. Open it (🚢 Fleet, or on the map) to give it a new contract.",
  "Les alertes": "Alerts",
  "La cloche rassemble ce qui demande votre attention : retards, navires immobilisés, risques à venir. Un chiffre rouge, c'est du nouveau.": "The bell gathers what needs your attention: delays, stopped ships, risks ahead. A red number means something new.",
  "Plein et réparations": "Fuel and repairs",
  "Au port, faites le plein ⛽ (le prix change d'un port à l'autre) ou réparez 🔧 : un navire usé a plus d'incidents et risque la détention. Au départ, le carburant manquant est acheté tout seul.": "In port, refuel ⛽ (the price changes from port to port) or repair 🔧: a worn ship has more incidents and risks detention. On departure, any missing fuel is bought automatically.",
  "Le bureau": "The office",
  "Votre bureau : trésorerie, prêts de la banque pour acheter d'autres navires, et le résultat de chaque navire (Résultats › Par navire).": "Your office: cash, bank loans to buy more ships, and each ship's results (Results › By ship).",
  "Le négoce": "Trading",
  "Autre façon de gagner : le négoce. Achetez vous-même une marchandise et revendez-la plus cher ailleurs. Plus risqué que les contrats, parfois bien plus rentable.": "Another way to earn: trading. Buy goods yourself and sell them for more elsewhere. Riskier than contracts, sometimes far more profitable.",
  "Bon vent !": "Fair winds!",
  "Vous savez l'essentiel. Le reste se découvre en jouant ; l'aide complète est dans le menu ☰. Bon vent !": "You know the essentials. The rest you'll discover by playing; the full help is in the ☰ menu. Fair winds!",
  "Visite guidée arrêtée. Le menu ☰ permet de la reprendre.": "Guided tour stopped. You can resume it from the ☰ menu.",
  "Visite guidée arrêtée.": "Guided tour stopped.",
  "Visite guidée reprise.": "Guided tour resumed.",
  "Visite guidée : oui": "Guided tour: on",
  "Visite guidée : non": "Guided tour: off",
  "Visite guidée : des bulles montrent les premiers gestes (on peut l'arrêter à tout moment)": "Guided tour: bubbles show the first moves (you can stop it at any time)",
  "Des bulles vont vous montrer les premiers gestes, au moment où ils servent. Vous pouvez arrêter la visite à tout moment, et la reprendre depuis le menu ☰.": "Bubbles will show you the first moves, right when you need them. You can stop the tour at any time and resume it from the ☰ menu.",
  "C'est parti": "Let's go",
  "Visite guidée : des bulles montrent les premiers gestes au moment où ils servent. Elle se lance depuis l'écran « Nouvelle partie », et le menu ☰ permet de l'arrêter ou de la reprendre à tout moment.": "Guided tour: bubbles show the first moves right when you need them. Start it from the “New game” screen; the ☰ menu lets you stop or resume it at any time.",
