  "{0} approche de la victoire « {1} » : {2} % du chemin. Touchez l'icône de cette victoire pour voir où il en est.": "{0} is nearing the victory “{1}”: {2}% of the way. Tap that victory's icon to see how far it is.",
  "Réagir": "Respond",
  "Votre compagnie est rachetée": "Your company has been bought",
  "Concurrents": "Rivals",
  "{0} veut racheter votre compagnie ({1}) : la vente se fera le {2} si l'offre tient toujours.": "{0} wants to buy your company ({1}): the sale will go through on {2} if the offer still stands.",
  "{0} pourraient racheter votre compagnie ({1}). Une meilleure réputation multiplie votre prix ; un niveau supérieur au leur vous protège.": "{0} could buy your company ({1}). A better reputation multiplies your price; a level above theirs protects you.",
  "{0} pourrait racheter votre compagnie ({1}). Une meilleure réputation multiplie votre prix ; un niveau supérieur au sien vous protège.": "{0} could buy your company ({1}). A better reputation multiplies your price; a level above theirs protects you.",
  "Prêteraient {0}, limités à {1} ({2}) par votre plafond d'encours, à {3}/an : environ {4} d'intérêts pour ce voyage. Remboursé à la vente.": "Would lend {0}, limited to {1} ({2}) by your loan cap, at {3}/year: about {4} of interest for this voyage. Repaid on sale.",
  "Plafond de vos prêts sur cargaison atteint : vendez d'abord une cargaison financée.": "Your cargo loan cap is reached: sell a financed cargo first.",
  "(dont {0} au prix de l'appel d'offres)": "(of which {0} at the tender price)",
  "Vente attendue à {0} : {1}": "Expected sale at {0}: {1}",
  ", voyage ≈ {0} ({1}). Résultat avant financement :": ", voyage ≈ {0} ({1}). Result before financing:",
  "{0} contre {1} jusqu'au {2}.": "{0} against {1} until {2}.",
  "🕴 {0} : {1}, jusqu'au {2}.": "🕴 {0}: {1}, until {2}.",
  "Navire à saboter": "Ship to sabotage",
  "Faire saboter ce navire ?": "Have this ship sabotaged?",
  "À sa prochaine escale, le navire perd {0} à {1} points d'état, sauf s'il a des gardes à bord. Réputation −{2} à coup sûr ; risque que l'affaire s'ébruite : {3} (réputation −{4}, amende de {5}). Son armateur entendra une rumeur et pourra mettre des gardes.": "At its next port call, the ship loses {0} to {1} condition points, unless it has guards on board. Reputation −{2} for certain; risk that the affair leaks: {3} (reputation −{4}, fine of {5}). Its owner will hear a rumour and can post guards.",
  "Un homme montera à bord à la prochaine escale.": "A man will board at the next port call.",
  "Sabotage :": "Sabotage:",
  "Faire saboter": "Have it sabotaged",
  "Guerre des prix à {0} jusqu'au {1} : ce chargeur vous paiera {2} % de moins (le prix affiché en tient compte).": "Price war at {0} until {1}: this shipper will pay you {2}% less (the price shown includes it).",
  "−{0} % guerre des prix": "−{0}% price war",
  "Ce chargeur fera traîner votre paiement ({0} à {1} jours) jusqu'au {2}.": "This shipper will drag out your payment ({0} to {1} days) until {2}.",
  "⏳ paiement retardé": "⏳ delayed payment",
  "Racheter un concurrent : prix = sa valeur nette × (1 + réputation ÷ {0}), payé comptant avec votre trésorerie nette (liquidités moins dettes et prêts sur cargaison), sans emprunt, et seulement s'il n'est pas d'un niveau supérieur au vôtre. Une compagnie de l'ordinateur accepte aussitôt ; un joueur a {1} jours pour réagir. Chaque coup contre un concurrent vous coûte de la réputation, peut faire scandale, et la victime en entend parler.": "Buying a rival: price = its net worth × (1 + reputation ÷ {0}), paid in cash from your net cash (cash minus debts and cargo loans), without borrowing, and only if it is not above your level. A computer company accepts at once; a player has {1} days to respond. Every move against a rival costs you reputation, may cause a scandal, and the victim hears about it.",
  "Vos actionnaires vous ont donné jusqu'au {0} : aucun rachat de votre compagnie possible d'ici là.": "Your shareholders gave you until {0}: nobody can buy your company before then.",
  "Offre de rachat de {0} : {1}": "Takeover offer from {0}: {1}",
  "· elle aboutira le {0} si elle tient toujours.": "· it will go through on {0} if it still stands.",
  "Peuvent vous racheter aujourd'hui ({0}) : {1}.": "Could buy you today ({0}): {1}.",
  "Niveau {0} · {1} navires · réputation {2} · valeur nette {3}": "Level {0} · {1} ships · reputation {2} · net worth {3}",
  "Prix de rachat :": "Takeover price:",
  "Racheter": "Buy out",
  "Plus aucun concurrent en lice.": "No rivals left in the race.",
  "{0} en cours jusqu'au {1}.": "{0} running until {1}.",
  "Une campagne de presse : environ {0} point de réputation perdu chaque semaine pendant huit semaines. Sa réputation baisse, son prix de rachat aussi.": "A press campaign: about {0} reputation point lost each week for eight weeks. Its reputation drops, and so does its takeover price.",
  "Dans un port de votre choix, pendant deux mois, les chargeurs lui paient le fret {0} % moins cher.": "In a port of your choice, for two months, shippers pay it {0}% less for freight.",
  "Un chargeur dont vous êtes le partenaire fidèle fait traîner ses paiements pendant trois mois ({0} à {1} jours de retard).": "A shipper whose loyal partner you are drags out its payments for three months ({0} to {1} days late).",
  "Vos relations font pression sur sa banque : son plafond de crédit est divisé par deux pendant six mois.": "Your contacts lean on its bank: its credit cap is halved for six months.",
  "Vos recruteurs débauchent les meilleurs marins d'un de ses navires : il perd un point d'expérience, un de vos navires en gagne un.": "Your recruiters poach the best sailors from one of its ships: it loses an experience point, one of your ships gains one.",
  "Niveau {0} requis": "Level {0} required",
  "Racheter {0} ?": "Buy out {0}?",
  "Prix : {0} payés comptant (valeur nette {1} × {2} pour sa réputation).": "Price: {0} paid in cash (net worth {1} × {2} for its reputation).",
  "Vous reprenez {0} navire(s), ses commandes et ses contrats, {1} de liquidités et {2} de dettes.": "You take over {0} ship(s), its orders and contracts, {1} in cash and {2} in debts.",
  "Votre réputation passerait de {0} à environ {1}.": "Your reputation would go from {0} to about {1}.",
  "Vous hériteriez aussi d'une part de son infamie.": "You would also inherit part of its infamy.",
  "{0} est dirigée par un joueur : il aura {1} jours pour réagir (demander un délai à ses actionnaires).": "{0} is run by a player: they will have {1} days to respond (ask their shareholders for time).",
  "Faire l'offre": "Make the offer",
