  "{0} en entendra parler (une rumeur, sans votre nom) et pourra parer le coup en payant. Risque que l'affaire s'ébruite : {1}.": "{0} will hear about it (a rumour, without your name) and can parry the move by paying. Risk that the affair leaks: {1}.",
  "Scandale : réputation −{0} et amende de {1}.": "Scandal: reputation −{0} and a fine of {1}.",
  "Scandale : réputation −{0}.": "Scandal: reputation −{0}.",
  "Lancer": "Launch",
  "C'est lancé.": "It's under way.",
  "{0} veut racheter {1}": "{0} wants to buy {1}",
  "{0} propose {1} à vos actionnaires. Sans réaction, la vente se fera le {2} si l'offre tient toujours : la partie serait alors finie pour {3}.": "{0} offers {1} to your shareholders. If you do nothing, the sale will go through on {2} if the offer still stands: the game would then be over for {3}.",
  "L'offre tombe d'elle-même si, d'ici là, votre prix dépasse sa trésorerie nette (votre réputation le multiplie : 1 + réputation ÷ {0}) ou si vous passez à un niveau supérieur au sien.": "The offer falls through by itself if, by then, your price exceeds its net cash (your reputation multiplies it: 1 + reputation ÷ {0}) or if you move to a level above theirs.",
  "Vous avez déjà demandé un délai pour cette offre.": "You have already asked for time on this offer.",
  "Vous pouvez demander six mois à vos actionnaires pour redresser la barre : {0} de chances qu'ils acceptent (selon votre réputation ; moins à chaque nouvelle demande). Ils vous protégeraient alors de tout rachat pendant six mois.": "You can ask your shareholders for six months to turn things around: {0} chance they agree (depending on your reputation; less with each new request). They would then protect you from any takeover for six months.",
