  "« Les assureurs se signent quand {0} les appelle. »": "“Insurers cross themselves when {0} calls.”",
  "« Au déjeuner, les cadres sourient dès qu'on prononce le nom de {0}. »": "“At lunch, executives smile as soon as someone says {0}.”",
  "« {0} ? C'est une nouvelle série ? »": "“{0}? Is that a new TV series?”",
