  "« Sur les quais, on connaît {0}. »": "“On the docks, people know {0}.”",
  "« Sur les quais, on demande {0}. »": "“On the docks, people ask for {0}.”",
  "« Contrairement aux journaux, les concurrents n'apprécient pas {0}. Ils se contentent de les copier. »": "“Unlike the newspapers, rivals don't like {0}. They just copy them.”",
  "« Les ministres veulent être photographiés sur le pont d'un navire de {0}. Les gens compétents aussi. »": "“Ministers want their picture taken on the deck of a {0} ship. So do competent people.”",
  "« Si Dieu avait disposé de {0} à l'époque, Noé serait resté fermier. »": "“If God had had {0} back then, Noah would have stayed a farmer.”",
  "Les chargeurs ne jurent que par vous ; la presse, elle, a d'autres mots.": "Shippers swear by you; the press has other words for you.",
  "La presse vous adore ; les chargeurs, eux, attendent encore leurs cargaisons.": "The press loves you; shippers are still waiting for their cargo.",
