  "Ne pas confondre avec la confiance des gangs, port par port, qui ne compte que dans l'ombre.": "Not to be confused with the gangs' trust, port by port, which only counts in the shadows.",
  "Chaque mois, un court bilan dit ce qui a fait bouger vos notes (Bureau → Compagnie). Ne pas confondre avec la confiance des gangs, port par port, qui ne compte que dans l'ombre.": "Each month, a short summary tells what moved your scores (Office → Company). Not to be confused with the gangs' trust, port by port, which only counts in the shadows.",
